  setInfo("Looking up the catchment area…");
  const area = await lookupCatchmentArea(stationId);

  const AREA_WARN_KM2 = 10_000;
  if (area && area.area > AREA_WARN_KM2) {
    await new Promise((resolve) => {
      renderInlineConfirm({
        message: `This catchment is ${fmt(area.area)} km². The forcing is taken at the gauge point, not averaged over the catchment, so a basin this size will not calibrate meaningfully. Run it anyway?`,
        onConfirm: resolve,
      });
    });
  }

  setInfo("Downloading 40 years of forcing…");
  const forcing = await fetchOpenMeteoForcing(stationId);

  setInfo("Fitting GR4J model…");
  const result = runGR4JCalibration(forcing);
  clearInfo();
  renderResult(result);
}
